/* ─── 3x5 Character Rendering ────────────────────────────────────────────── */
/**
 * @brief  Draws a single 3x5 character into the canvas back-buffer.
 * @param  x,y    The top-left pixel coordinates where the character cell starts.
 * @param  c      The ASCII character to draw (printable characters 0x20 to 0x7E).
 * @param  r,g,b  Color composition values (0–255).
 */
static inline void HUB75_DrawChar3x5(int16_t x, int16_t y, char c,
                                     uint8_t r, uint8_t g, uint8_t b)
{
    /* Fallback protection: replace unprintable characters with a question mark */
    if (c < FONT3X5_FIRST || c > FONT3X5_LAST) {
        c = '?';
    }

    /* Zero-index the ASCII value to look up its location in the local table */
    const uint8_t *glyph = font3x5[(uint8_t)(c - FONT3X5_FIRST)];

    /* Iterate through the 3 columns of the glyph */
    for (uint8_t col = 0; col < FONT3X5_W; col++) {
        uint8_t col_data = glyph[col];

        /* Iterate through the 5 vertical rows of the current column */
        for (uint8_t row = 0; row < FONT3X5_H; row++) {
            /* Check if the specific row bit is high */
            if (col_data & (1u << row)) {
                int16_t px = x + col;
                int16_t py = y + row;

                /* Bounds verification: drop individual pixels that fall outside the screen */
                if (px >= 0 && px < HUB75_COLS && py >= 0 && py < HUB75_ROWS) {
                    HUB75_SetPixel((uint8_t)px, (uint8_t)py, r, g, b);
                }
            }
        }
    }
}

/* ─── 3x5 Ultra-Compact Text Rendering ───────────────────────────────────── */
/**
 * @brief  Draws a static string into the canvas back-buffer using 3x5 metrics.
 */
static inline void HUB75_DrawString3x5(int16_t x, int16_t y, const char *str,
                                       uint8_t r, uint8_t g, uint8_t b)
{
    while (*str) {
        if (x >= HUB75_COLS) break; /* Performance break: stop if text passes right border */
        HUB75_DrawChar3x5(x, y, *str, r, g, b);
        x += FONT3X5_CELL_W; /* Advance position by character width + 1px spacing */
        str++;
    }
}

/* ─── 3x5 Marquee Scrolling ──────────────────────────────────────────────── */
/**
 * @brief  Draws a 3x5 string with a horizontal offset for smooth scroll animations.
 */
static inline void HUB75_ScrollString3x5(int16_t x_offset, int16_t y, const char *str,
                                         uint8_t r, uint8_t g, uint8_t b)
{
    int16_t x = x_offset;
    while (*str) {
        /* Pipelined bounding check: only draw if character is partially or fully visible */
        if (x + FONT3X5_W > 0 && x < HUB75_COLS) {
            HUB75_DrawChar3x5(x, y, *str, r, g, b);
        }
        x += FONT3X5_CELL_W;
        str++;
    }
}

#endif /* HUB75_FONT3X5_H */
